// Evolution routes, grouped by source in dex order (TsDexEntry::evoFirst), in the
// game's order within a source. Only routes between raisable forms are kept.
// De-digivolution is any route read backwards.
struct TsEvo {
  uint16_t from, to;      // dex ids
  uint16_t min[TS_STAT_COUNT];  // raw stat minimums (TS_STAT_*; 0 = none)
  uint8_t minLevel;       // from the SP minimum (SP is dropped); 0 = none
  uint8_t rank;           // Agent Rank needed; 0 = none
};
#define TS_EVO_COUNT 1025
